const html_raw = $json.styled_html || '';
let data = Array.isArray($json.data) ? $json.data : [];
const groupByField = $json.group_by;
const isInsertMode = data.length === 0 && html_raw.includes('<form');

// INSERT mode: if no data and template is a form, render with empty fields
if (isInsertMode) {
  data = [{}];
}

// --- Form select enrichment ---
// Detect {{{template_name:field_name}}} tokens
const selectTokenRegex = /\{\{\{([a-zA-Z0-9_]+):([a-zA-Z0-9_]+)\}\}\}/g;
const selectConfigs = [];
let selectMatch;
while ((selectMatch = selectTokenRegex.exec(html_raw)) !== null) {
  selectConfigs.push({ templateName: selectMatch[1], fieldName: selectMatch[2], fullToken: selectMatch[0] });
}

let html = html_raw;

if (selectConfigs.length > 0 && data.length > 0) {
  const record = data[0];
  for (const config of selectConfigs) {
    // Strip f_ prefix from template name for lookup
    const baseTemplateName = config.templateName.startsWith('f_') ? config.templateName.slice(2) : config.templateName;
    const currentVal = record[config.fieldName] || 0;
    try {
      const result = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://n8n.whatsfresh.app/webhook/server-query',
        body: {
          query: "SELECT studio.api_select_form(:template_name::text, :current_val::int, :field_name::text) as html",
          params: { template_name: baseTemplateName, current_val: currentVal, field_name: config.fieldName },
          source: 'styled-html'
        },
        json: true
      });

      let selectHtml = '';
      if (Array.isArray(result) && result[0]?.html) {
        selectHtml = result[0].html;
      } else if (typeof result === 'string') {
        selectHtml = result;
      }
      // Replace the full token directly with the rendered HTML
      html = html.split(config.fullToken).join(selectHtml);
    } catch (e) {
      html = html.split(config.fullToken).join('');
    }
  }
}
// --- End form select enrichment ---

const eachRegex = /\{\{#each data\}\}([\s\S]*?)\{\{\/each\}\}/;
const match = html.match(eachRegex);

if (match) {
  const rowTemplate = match[1];
  const rows = data.map((item, index) => {
    let row = '';
    if (groupByField && (index === 0 || item[groupByField] !== data[index-1][groupByField])) {
      row += `<tr class="group-hdr"><td colspan="99"><strong>${item[groupByField]}</strong></td></tr>`;
    }
    row += rowTemplate;

    // Preserve {{slot:*}} patterns by temporarily replacing them
    const slotRegex = /\{\{slot:[^\}]+\}\}/g;
    const slots = [];
    let slotIndex = 0;
    const placeholder = '___SLOT_PLACEHOLDER_';
    row = row.replace(slotRegex, (match) => {
      slots.push(match);
      return placeholder + (slotIndex++) + '___';
    });

    // Replace data field placeholders (using function replacer to avoid $ interpretation)
    for (const [key, value] of Object.entries(item)) {
      const safeVal = String(value ?? '');
      row = row.replace(new RegExp(`\\{\\{\\{${key}\\}\\}\\}`, 'g'), () => safeVal);
      row = row.replace(new RegExp(`\\{\\{${key}\\}\\}`, 'g'), () => safeVal);
    }

    // Restore {{slot:*}} patterns
    for (let i = 0; i < slots.length; i++) {
      row = row.replace(placeholder + i + '___', slots[i]);
    }

    // Handle {{#if condition}}content{{/if}} blocks
    const ifRegex = /\{\{#if\s+(\w+)\}\}(.*?)\{\{\/if\}\}/g;
    row = row.replace(ifRegex, (match, condition, content) => {
      return item[condition] ? content : '';
    });
    return row;
  }).join('');
  // Use function replacer to avoid $ back-reference interpretation in compiled rows
  html = html.replace(eachRegex, () => rows);
}

return [{ json: { html, isInsertMode } }];

let html = $json.html || '';
const isInsertMode = $json.isInsertMode || false;

// Only clear remaining placeholders in INSERT mode (empty form)
if (isInsertMode) {
  // Preserve {{slot:*}} patterns
  const slotRegex = /\{\{slot:[^\}]+\}\}/g;
  const slots = [];
  let idx = 0;
  const ph = '___SLOT_PH_';
  html = html.replace(slotRegex, (m) => { slots.push(m); return ph + (idx++) + '___'; });

  // Clear unreplaced triple and double-brace field tokens
  html = html.replace(/\{\{\{[a-zA-Z0-9_]+\}\}\}/g, '');
  html = html.replace(/\{\{[a-zA-Z0-9_]+\}\}/g, '');

  // Restore slot patterns
  for (let i = 0; i < slots.length; i++) {
    html = html.replace(ph + i + '___', slots[i]);
  }
}

return [{ json: { html } }];
